from pathlib import Path
import json
root=Path(__file__).resolve().parents[4]
episode=Path(__file__).resolve().parent.parent
source=root/'video/src/NamyangjuV2.tsx'
text=source.read_text(encoding='utf-8')
start=text.index('function Diagram(')
end=text.index('\n',start)
new=r'''function Diagram({shot}:{shot:any}){
 const f=useCurrentFrame(),key=shot.asset_request,d=diagrams[key]||{title:shot.purpose,labels:['현재','준비 단계','입주하는 해'],sub:['이미 이용 가능','계획 · 목표 구분','내 생활의 조건 확인']};
 const focus=Math.min(2,Math.floor(f/(shot.frames/3))), calendar=['calendar','gtx_timeline','school_calendar','company_timeline'].includes(key), network=['commute','station_diagram','transport_status'].includes(key), document=['official_document','school_document','price_source'].includes(key), metrics=['industrial_size','we_budget','supply'].includes(key);
 const reveal=(i:number)=>({opacity:clamp(f,i*18,i*18+24,0,1),transform:`translateY(${clamp(f,i*18,i*18+24,35,0)}px)`});
 return <AbsoluteFill style={{background:C.cream}}><Header chapter={shot.chapter_id}/><div style={{position:'absolute',left:96,top:105,fontSize:52,fontWeight:700,width:1700}}>{d.title}</div>
 {calendar?<div style={{position:'absolute',left:96,right:96,top:260,display:'flex',gap:48}}>{d.labels.map((label:string,i:number)=><div key={i} style={{...reveal(i),flex:1,height:500,background:'white',borderRadius:20,boxShadow:'0 12px 25px #0000000b',overflow:'hidden',border:focus===i?`4px solid ${C.blue}`:'4px solid transparent'}}><div style={{height:85,background:i===2?C.amber:C.blue,color:i===2?C.ink:'white',padding:'22px 30px',fontSize:31,fontWeight:700}}>{['일정 01','일정 02','일정 03'][i]}</div><div style={{padding:'55px 25px',textAlign:'center'}}><div style={{fontSize:49,fontWeight:700,lineHeight:1.3}}>{label}</div><div style={{marginTop:40,fontSize:29,color:C.grey}}>{d.sub[i]}</div><div style={{marginTop:40,height:6,width:clamp(f,i*18,i*18+70,0,100)+'%',background:C.blue}}/></div></div>)}</div>:
 network?<div style={{position:'absolute',left:140,right:140,top:260}}>{d.labels.map((label:string,i:number)=><div key={i} style={{...reveal(i),display:'flex',alignItems:'center',gap:36,marginBottom:32}}><div style={{width:95,height:95,borderRadius:48,background:focus===i?C.amber:C.blue,display:'flex',alignItems:'center',justifyContent:'center'}}><Icon i={key==='commute'?[2,1,0][i]:1} size={59} color={focus===i?C.ink:'white'}/></div><div style={{height:100,flex:1,background:'white',borderLeft:`8px solid ${i===0?C.blue:i===1?'#42a37b':C.amber}`,padding:'23px 32px',display:'flex',alignItems:'center',justifyContent:'space-between'}}><b style={{fontSize:40}}>{label}</b><span style={{fontSize:29,color:C.grey}}>{d.sub[i]}</span></div></div>)}<div style={{fontSize:25,color:C.grey,marginTop:25}}>위치·거리 축척을 사용하지 않은 관계도</div></div>:
 document?<div style={{position:'absolute',left:290,right:290,top:245,background:'white',padding:'35px 55px',borderTop:`12px solid ${C.blue}`,boxShadow:'0 12px 35px #00000012'}}><div style={{fontSize:24,color:C.grey,marginBottom:28}}>발표·공고를 읽는 핵심 조건</div>{d.labels.map((label:string,i:number)=><div key={i} style={{...reveal(i),padding:'24px 0',borderTop:'2px solid #e5e3dd',display:'flex',justifyContent:'space-between',background:focus===i?'#fff5bd':'white'}}><b style={{fontSize:38}}>{label}</b><span style={{fontSize:29,color:C.grey}}>{d.sub[i]}</span></div>)}</div>:
 metrics?<div style={{position:'absolute',left:96,right:96,top:270,display:'flex',gap:35}}>{d.labels.map((label:string,i:number)=><div key={i} style={{...reveal(i),flex:1,height:415,padding:'40px 30px',background:i===0?C.blue:'white',color:i===0?'white':C.ink,borderBottom:focus===i?`12px solid ${C.amber}`:'12px solid transparent'}}><div style={{fontSize:23,opacity:.7}}>확인 항목 0{i+1}</div><div style={{fontSize:54,fontWeight:700,lineHeight:1.3,marginTop:58}}>{label}</div><div style={{fontSize:28,lineHeight:1.5,marginTop:35,opacity:.8}}>{d.sub[i]}</div></div>)}</div>:
 <div style={{position:'absolute',left:140,right:140,top:270}}>{d.labels.map((label:string,i:number)=><div key={i} style={{...reveal(i),display:'flex',alignItems:'center',marginBottom:28,gap:36}}><div style={{width:100,height:100,background:focus===i?C.amber:'#e8e5dc',fontSize:45,fontWeight:700,display:'flex',alignItems:'center',justifyContent:'center',color:C.blue}}>0{i+1}</div><div style={{flex:1,padding:'22px 30px',borderBottom:'3px solid #d8d5cc',display:'flex',justifyContent:'space-between'}}><b style={{fontSize:40}}>{label}</b><span style={{fontSize:29,color:C.grey}}>{d.sub[i]}</span></div></div>)}</div>}
 <Footer text={shot.source_urls?.length?'자료: 남양주시 · 국토교통부 · LH · 교육지원청의 해당 발표/공고 | 목표·예정은 실제 이용 완료와 구분':'자료 읽기의 기준을 설명한 자체 도식 · 실제 위치나 통근시간을 표시한 지도 아님'}/></AbsoluteFill>;
}'''
text=text[:start]+new+text[end:]
(root/'video/src/NamyangjuV3.tsx').write_text(text,encoding='utf-8')
renderer=(episode/'editor/render_v2_final.cjs').read_text(encoding='utf-8').replace("'render_v2'","'render_v3'").replace('NamyangjuV2.tsx','NamyangjuV3.tsx').replace('namyangju-wangsuk_v2.mp4','namyangju-wangsuk_v3.mp4')
(episode/'editor/render_v3_final.cjs').write_text(renderer,encoding='utf-8')
statepath=episode/'state.json';state=json.loads(statepath.read_text(encoding='utf-8'));state.update(stage='motion_rebuild_v3_render',full_video_v2_complete=True,full_video_v2_quality_approved=False,active_tasks=['editor_render_v3','video_quality_qa_v3']);statepath.write_text(json.dumps(state,ensure_ascii=False,indent=2),encoding='utf-8')
print('v2 preserved; v3 semantic graphics prepared')
